"""Campaign 05 targets (all binary frames (T,H,W) uint8) and structures.

Targets: Bad Apple 'ba<w>_<start>_<len>' and the tiny synthetic clips via exp03 `target`;
'translate24' (moving block, 24x24, 12 frames); positive controls 'pcA'/'pcB' generated by a small
KNOWN circuit from a fixed random first frame. Suffix ':p<L>' = first L frames (prefix);
'pcA_long' etc. = longer runs of the same known circuit (generalization diagnostics).
Structures: name -> (k hidden bits, hidden_seen_by, S).
"""
import os, sys
import numpy as np
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ca import costs
from ca.rule import family_taps, rollout
from ca.synthetic import translate

STRUCTS = {f"k{k}{'s' if seen == 'moore' else ''}_S{S}": (k, seen, S)
           for k in (0, 1, 2) for seen in ("self", "moore") for S in (1, 2, 4, 8) if not (k == 0 and seen == "moore")}

# known circuits (gates over pool [10 F_priv(1) taps, gates], tt bit q = f(a=q>>1, b=q&1)); XOR = 6
# pcA: v' = (N xor W) xor h ; h' = centre            (2 gates, S=1)
# pcB: v' = maj-like mix of N, W, h ; h' = v xor h  (4 gates, S=2)
KNOWN = {"pcA": dict(gates=[(6, 1, 3), (6, 9, 10)], outputs=[11, 4], k=1, S=1, size=12, T=6, seed=0),
         "pcB": dict(gates=[(6, 1, 3), (8, 4, 10), (7, 9, 11), (6, 4, 9)], outputs=[12, 13], k=1, S=2, size=12, T=6, seed=1)}


def known(name, T=None):
    d = KNOWN[name]; taps = family_taps(d["k"])
    f0 = (np.random.default_rng(d["seed"]).random((d["size"], d["size"])) < 0.5).astype(np.uint8)
    luts = costs.eval_circuit(d["gates"], d["outputs"], len(taps))
    vis, _, _ = rollout(f0, taps, luts, T or d["T"], d["S"])
    return vis.astype(np.uint8)


def target(name):
    if ":p" in name:
        base, L = name.split(":p"); return target(base)[:int(L)]
    if name == "translate24":
        return translate(24)
    if name in KNOWN:
        return known(name)
    if name.endswith("_long") and name[:-5] in KNOWN:
        return known(name[:-5], 3 * KNOWN[name[:-5]]["T"])
    from exp03_sat_ablation import target as t3
    return t3(name)
